if (count($interpretations) !== 100) {
	fwrite(STDERR, 'Expected 100 interpretations, got ' . count($interpretations) . "\n");
	exit(1);
}
if (count($verses) !== 100) {
	fwrite(STDERR, 'Expected 100 verses, got ' . count($verses) . "\n");
	exit(1);
}

$main = json_decode(file_get_contents($root . '/storage/new_testament_quotes.json'), true, 512, JSON_THROW_ON_ERROR);
for ($i = 0; $i < 100; $i++) {
	$main['quotes'][] = [
		'book' => $verses[$i]['book'],
		'chapter' => $verses[$i]['chapter'],
		'verse' => $verses[$i]['verse'],
		'text' => $verses[$i]['text'],
		'interpretation' => $interpretations[$i],
	];
}
$n = count($main['quotes']);
$main['count'] = $n;
$main['description'] = $n . ' коротких цитат из Нового Завета с толкованиями (Синодальный перевод)';

$out = json_encode($main, JSON_UNESCAPED_UNICODE | JSON_PRETTY_PRINT);
if ($out === false) {
	exit(1);
}
if (file_put_contents($root . '/storage/new_testament_quotes.json', $out . "\n") === false) {
	exit(1);
}
echo "OK: {$n} quotes\n";
